#include <algorithm>

using namespace std;

string s;
long n, len;

bool check(long a) {
    for (long i = 1; i <= a - n; ++i) {
        if (s[len - i] != s[len - i - a])
            return false;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> s;
    len = s.length();
    cin >> n;

    long min_val, max_val;
    if (n > len)
        min_val = (len + n) / 2;
    else
        min_val = n;

    max_val = (len + n) / 2;

    long temp = 0;
    for (long i = 0; i < len; ++i) {
        for (long j = 1; j * 2 + i <= len; ++j) {
            bool key = true;
            for (long k = 1; k <= j; ++k) {
                if (s[i + k - 1] != s[i + k + j - 1]) {
                    key = false;
                    break;
                }
            }
            if (key && j > temp)
                temp = j;
        }
    }

    long ans = 0;
    for (long i = max_val; i >= min_val && ans == 0; --i) {
        if (check(i))
            ans = i;
    }

    if (min_val > ans) ans = min_val;
    if (temp > ans) ans = temp;

    cout << 2 * ans << endl;

    return 0;
}

